package com.ems.controller; import com.ems.dao.EmployeeDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; @WebServlet("/employees") public class EmployeeListServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{r.setAttribute("employees",new EmployeeDAO().findAll(r.getParameter("search"),r.getParameter("department"),r.getParameter("status")));r.setAttribute("search",r.getParameter("search"));r.setAttribute("department",r.getParameter("department"));r.setAttribute("status",r.getParameter("status"));r.getRequestDispatcher("/WEB-INF/views/employees.jsp").forward(r,s);}catch(Exception e){getServletContext().log("Employee list failed",e);r.setAttribute("error","Employee records are temporarily unavailable.");r.getRequestDispatcher("/WEB-INF/views/employees.jsp").forward(r,s);}}}
